func run()error{b,t,e:=fixture.Open();if e!=nil{return e};p,e:=fixture.Payload(b,t);if e!=nil{return e};if len(p)<4{return fmt.Errorf("short sample")};n:=binary.BigEndian.Uint32(p);if n==0||uint64(n)>uint64(len(p)-4){return fmt.Errorf("bad first NAL")};xs,e:=mp4.ExtractBoxWithPayload(bytes.NewReader(b),nil,mp4.BoxPath{mp4.BoxTypeMoov(),mp4.BoxTypeTrak(),mp4.BoxTypeMdia(),mp4.BoxTypeMinf(),mp4.BoxTypeStbl(),mp4.BoxTypeStsd(),mp4.BoxTypeAvc1(),mp4.BoxTypeAvcC()});if e!=nil{return e};if len(xs)!=1{return fmt.Errorf("avcC count %d",len(xs))};c:=xs[0].Payload.(*mp4.AVCDecoderConfiguration);var enc bytes.Buffer;if _,e=mp4.Marshal(&enc,c,mp4.Context{});e!=nil{return e};var decoded mp4.AVCDecoderConfiguration;decoded.SetType(mp4.BoxTypeAvcC());if _,e=mp4.Unmarshal(bytes.NewReader(enc.Bytes()),uint64(enc.Len()),&decoded,mp4.Context{});e!=nil{return e};if decoded.NumOfSequenceParameterSets==0||decoded.NumOfPictureParameterSets==0{return fmt.Errorf("missing parameters")};fmt.Printf("BASELINE_AVC track=%d samples=%d chunks=%d timescale=%d first_sample_bytes=%d first_nal_type=%d\n",t.TrackID,len(t.Samples),len(t.Chunks),t.Timescale,len(p),p[4]&31);fmt.Printf("AVCC_ROUNDTRIP sps=%d pps=%d source_sample_sha256=%x\n",decoded.NumOfSequenceParameterSets,decoded.NumOfPictureParameterSets,sha256.Sum256(p));return nil}
